        tokio::time::sleep(Duration::from_millis(1)).await;

        slots.on_hook(&hook(
            A,
            HookEvent::SessionEnd {
                reason: Some("clear".into()),
                claude_pid: Some(10),
            },
        ));
        slots.on_hook(&hook(
            B,
            HookEvent::SessionStart {
                source: Some("clear".into()),
                claude_pid: Some(10),
                parent_claude_pid: None,
            },
        ));
        slots.on_agent(queued);
