    /// Slots with session A streaming through agent conn 1, its first read
    /// (from 0) asked; nothing ever reaches Telegram.
    fn asked_slots(dir: &TempDir) -> Slots {
        let path = transcript_file(dir, A);
        let mut slots = stalled_slots(dir, stream_options());
        slots.on_hook(&start_with(A, 10, &path, "startup"));
        slots
            .registry
            .topic_created(SlotId(0), Chat::GROUP, 100, "a", None);
        let (to_agent, mut from_hub) = mpsc::channel(4);
        slots.on_agent(AgentEvent::Registered {
            conn: 1,
            register: Register {
                session_id: A.into(),
                host: "box".into(),
                cwd: CWD.into(),
                claude_pid: Some(10),
                verdict_ack: true,
                transcript_reads: true,
                console_keys: false,
                console_commands: false,
                client: None,
                files: false,
                session_reads: false,
                status_lines: false,
                private_place: false,
                enrolled: None,
                heartbeat: false,
            },
            to_agent,
        });
        slots.pump();
        assert!(matches!(
            from_hub.try_recv(),
            Ok(HubMsg::TranscriptRead { from: Some(0), .. })
        ));
        slots
    }

    fn one_prompt_chunk(session: &str) -> AgentMsg {
        AgentMsg::TranscriptChunk {
            session_id: session.into(),
            from: 0,
            to: 10,
            lines: vec![StreamLine {
                end: 10,
                items: vec![crate::wire::StreamItem::Prompt { text: "one".into() }],
            }],
            missing: false,
            more: false,
            reset: false,
        }
    }

    fn stream_offset(slots: &Slots) -> Option<u64> {
        slots.registry.sessions[A].stream.as_ref().unwrap().offset
    }

    #[tokio::test]
    async fn a_chunk_for_another_session_on_the_connection_is_dropped() {
        let dir = TempDir::new("slots-stream-foreign-chunk");
        let mut slots = asked_slots(&dir);
        let message = |msg| AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg,
        };
        slots.on_agent(message(one_prompt_chunk(B)));
        assert!(slots.streams[A].reading.is_some(), "the read still waits");
        assert!(!slots.streams.contains_key(B));
        assert_eq!(slots.queued_messages, 0);
        assert_eq!(slots.streams[A].read_at, Some(0));
        // The same chunk for the bound session is taken.
        slots.on_agent(message(one_prompt_chunk(A)));
        assert!(slots.streams[A].reading.is_none());
        assert_eq!(slots.queued_messages, 1);
        assert_eq!(slots.streams[A].read_at, Some(10));
    }

    /// TASK-023: an answer whose turn end was read before its `Stop` rides
    /// the stream behind the lines of its turn; when a line before it is
    /// refused (and the answer dropped unsent behind it), the rewind holds it
    /// again and the re-read turn end lets it go after the lines again.
    #[tokio::test]
    async fn an_answer_behind_a_refused_line_is_held_again_and_follows_the_re_read_lines() {
        use crate::wire::StreamItem;
        let dir = TempDir::new("slots-stream-answer-refused");
        let mut slots = asked_slots(&dir);
        let chunk = || AgentMsg::TranscriptChunk {
            session_id: A.into(),
            from: 0,
            to: 20,
            lines: vec![
                StreamLine {
                    end: 10,
                    items: vec![StreamItem::Prompt { text: "one".into() }],
                },
                StreamLine {
                    end: 20,
                    items: vec![StreamItem::TurnEnd],
                },
            ],
            missing: false,
            more: false,
            reset: false,
        };
        let message = |msg| AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg,
        };
        slots.on_agent(message(chunk()));
        assert_eq!(slots.streams[A].ends_unclaimed, [20]);
        slots.on_hook(&stop(A, Some("done")));
        let live = &slots.streams[A];
        assert!(live.ends_unclaimed.is_empty(), "the Stop took the turn end");
        assert_eq!(live.unanswered(), 2, "the answer rides the stream");
        assert!(live.held.is_empty());

        // The line is refused; the answer behind it never left (dropped).
        slots.on_stream_done(
            A,
            1,
            Some(Err(ApiError::Telegram {
                code: 502,
                description: "Bad Gateway".into(),
            })),
        );
        slots.on_stream_done(A, 2, None);
        let live = &slots.streams[A];
        // TASK-024: kept as sent until the re-read after the retry.
        assert!(live.stuck() && live.rewind_at.is_some() && live.reading.is_none());
        assert_eq!(live.answer_numbers(), [(2, "done")], "not lost");
        assert_eq!(stream_offset(&slots), Some(0));

        // The re-read rewinds (the answer is held again): the line, then the
        // answer at its turn end.
        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(message(chunk()));
        let live = &slots.streams[A];
        assert!(live.held.is_empty());
        assert_eq!(live.unanswered(), 2);
        slots.on_stream_done(A, 1, Some(Ok(Outcome::Sent(Message::default()))));
        slots.on_stream_done(A, 2, Some(Ok(Outcome::Sent(Message::default()))));
        assert_eq!(stream_offset(&slots), Some(20));
        assert!(slots.streams[A].held.is_empty());
        assert_eq!(slots.queued_messages, 0);
    }

    /// TASK-023 review I1 (the reviewer's probe): two turns in one read,
    /// both answers held before it. Turn 2's prompt is refused, its answer
    /// dropped unsent behind it; the rewind re-reads turn 1's end too, whose
    /// answer is in the topic. That end lets nothing go and is not left for
    /// a later `Stop`: turn 2's answer goes at its own end, after `> two`.
    #[tokio::test]
    async fn a_turn_end_read_again_lets_only_its_own_answer_go() {
        use crate::wire::StreamItem;
        let dir = TempDir::new("slots-stream-answer-pairing");
        let mut slots = asked_slots(&dir);
        let chunk = || AgentMsg::TranscriptChunk {
            session_id: A.into(),
            from: 0,
            to: 40,
            lines: vec![
                StreamLine {
                    end: 10,
                    items: vec![StreamItem::Prompt { text: "one".into() }],
                },
                StreamLine {
                    end: 20,
                    items: vec![StreamItem::TurnEnd],
                },
                StreamLine {
                    end: 30,
                    items: vec![StreamItem::Prompt { text: "two".into() }],
                },
                StreamLine {
                    end: 40,
                    items: vec![StreamItem::TurnEnd],
                },
            ],
            missing: false,
            more: false,
            reset: false,
        };
        let message = |msg| AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg,
        };
        let ok = || Some(Ok(Outcome::Sent(Message::default())));
        slots.on_hook(&stop(A, Some("first")));
        slots.on_hook(&stop(A, Some("second")));
        slots.on_agent(message(chunk()));
        // 1 "> one", 2 "first", 3 "> two", 4 "second".
        assert_eq!(
            slots.streams[A].answer_numbers(),
            [(2, "first"), (4, "second")]
        );
        slots.on_stream_done(A, 1, ok());
        slots.on_stream_done(A, 2, ok());
        slots.on_stream_done(
            A,
            3,
            Some(Err(ApiError::Telegram {
                code: 502,
                description: "Bad Gateway".into(),
            })),
        );
        slots.on_stream_done(A, 4, None);
        let live = &slots.streams[A];
        // TASK-024: the re-read from the start of the read rewinds it.
        assert!(live.stuck() && live.rewind_at.is_some());
        assert_eq!(stream_offset(&slots), Some(0));

        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(message(chunk()));
        let live = &slots.streams[A];
        // 1 "> one" again, 2 "> two", 3 "second": "first" is not sent twice
        // and "second" follows its own lines.
        assert_eq!(live.answer_numbers(), [(3, "second")]);
        assert_eq!(live.unanswered(), 3);
        assert!(live.held.is_empty());
        assert!(
            live.ends_unclaimed.is_empty(),
            "no stale turn end for the next Stop: {:?}",
            live.ends_unclaimed
        );
        // The next turn's answer waits for its own turn end.
        slots.on_hook(&stop(A, Some("third")));
        let held: Vec<&str> = slots.streams[A]
            .held
            .iter()
            .map(|h| h.answer.as_str())
            .collect();
        assert_eq!(held, ["third"]);
    }

    /// TASK-023 review I1: an answer that claimed a turn end already behind
    /// the committed offset, then was dropped behind a refused line, goes
    /// first on the re-read (its lines are in the topic), not at the next
    /// turn's end.
    #[tokio::test]
    async fn an_answer_held_again_whose_turn_end_is_committed_goes_first_on_the_re_read() {
        use crate::wire::StreamItem;
        let dir = TempDir::new("slots-stream-answer-overdue");
        let mut slots = asked_slots(&dir);
        let message = |msg| AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg,
        };
        let ok = || Some(Ok(Outcome::Sent(Message::default())));
        slots.on_agent(message(AgentMsg::TranscriptChunk {
            session_id: A.into(),
            from: 0,
            to: 20,
            lines: vec![
                StreamLine {
                    end: 10,
                    items: vec![StreamItem::Prompt { text: "one".into() }],
                },
                StreamLine {
                    end: 20,
                    items: vec![StreamItem::TurnEnd],
                },
            ],
            missing: false,
            more: false,
            reset: false,
        }));
        slots.on_stream_done(A, 1, ok());
        assert_eq!(stream_offset(&slots), Some(20));
        // The Stop comes after its turn end is committed.
        slots.on_hook(&stop(A, Some("first")));
        assert_eq!(slots.streams[A].answer_numbers(), [(2, "first")]);
        let two = || AgentMsg::TranscriptChunk {
            session_id: A.into(),
            from: 20,
            to: 30,
            lines: vec![StreamLine {
                end: 30,
                items: vec![StreamItem::Prompt { text: "two".into() }],
            }],
            missing: false,
            more: false,
            reset: false,
        };
        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(message(two()));
        slots.on_stream_done(
            A,
            2,
            Some(Err(ApiError::Telegram {
                code: 502,
                description: "Bad Gateway".into(),
            })),
        );
        slots.on_stream_done(A, 3, None);
        let live = &slots.streams[A];
        // TASK-024: the re-read from the committed offset rewinds it.
        assert!(live.stuck() && live.rewind_at.is_some());
        assert_eq!(stream_offset(&slots), Some(20));

        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(message(two()));
        let live = &slots.streams[A];
        // 1 "first", 2 "> two".
        assert_eq!(live.answer_numbers(), [(1, "first")]);
        assert_eq!(live.unanswered(), 2);
        assert!(live.held.is_empty());
    }

    /// TASK-023 review I2: a streamed answer counts against
    /// [`MAX_QUEUED_MESSAGES`]; one that does not fit is dropped like a plain
    /// one, and nothing of it stays tracked in the stream.
    #[tokio::test]
    async fn a_streamed_answer_past_the_message_cap_is_dropped_untracked() {
        let dir = TempDir::new("slots-stream-answer-cap");
        let mut slots = asked_slots(&dir);
        slots.queued_messages = MAX_QUEUED_MESSAGES;
        for n in 0..=stream::MAX_HELD {
            slots.on_hook(&stop(A, Some(format!("answer {n}").as_str())));
        }
        // The oldest was pushed out of the held ones with no room left.
        assert_eq!(slots.streams[A].held.len(), stream::MAX_HELD);
        assert_eq!(slots.queued_messages, MAX_QUEUED_MESSAGES);
        assert_eq!(slots.streams[A].unanswered(), 0, "nothing tracked");
        assert!(slots.overflow_warned);
        // With room the next pushed-out answer rides the stream.
        slots.queued_messages = 0;
        slots.on_hook(&stop(A, Some("late")));
        assert_eq!(slots.queued_messages, 1);
        assert_eq!(slots.streams[A].answer_numbers(), [(1, "answer 1")]);
    }

    fn bad_gateway() -> Option<Delivery> {
        Some(Err(ApiError::Telegram {
            code: 502,
            description: "Bad Gateway".into(),
        }))
    }

    /// TASK-024 item 1: A ends while its refused line waits for the retry,
    /// and B takes the slot. The line goes again as it was (A cannot read any
    /// more), and B's separator waits until it is in the topic.
    #[tokio::test]
    async fn a_session_ending_while_its_stream_waits_sends_the_refused_lines_before_the_next_separator()
     {
        let dir = TempDir::new("slots-stream-drain");
        let mut slots = asked_slots(&dir);
        slots.on_agent(AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg: one_prompt_chunk(A),
        });
        slots.on_stream_done(A, 1, bad_gateway());
        assert!(slots.streams[A].stuck());
        slots.on_hook(&hook(
            A,
            HookEvent::SessionEnd {
                reason: None,
                claude_pid: Some(10),
            },
        ));
        let path = transcript_file(&dir, B);
        slots.on_hook(&start_with(B, 11, &path, "startup"));
        // The stalled scheduler never answers the title edit of A's start.
        slots.registry.slots[0].views[0].busy = false;
        let slot = &slots.registry.slots[0];
        assert_eq!(slot.current_session.as_deref(), Some(B));
        assert!(slot.views[0].pending_separator.is_some());
        slots.pump();
        assert!(slots.streams.contains_key(A), "kept: its line is not out");
        assert_eq!(slots.queued_messages, 0, "not before its retry");
        assert!(
            !slots.registry.slots[0].views[0].busy,
            "the separator waits"
        );
        // The retry is due: the line goes again, the separator still waits.
        slots.streams.get_mut(A).unwrap().rewind_at = Some(Instant::now());
        slots.pump();
        assert_eq!(slots.queued_messages, 1);
        assert_eq!(slots.streams[A].unanswered(), 1);
        assert_eq!(slots.streams[A].resends, 1);
        assert!(!slots.registry.slots[0].views[0].busy);
        slots.on_stream_done(A, 1, Some(Ok(Outcome::Sent(Message::default()))));
        assert_eq!(stream_offset(&slots), Some(10), "the line is in the topic");
        slots.pump();
        assert!(!slots.streams.contains_key(A), "forgotten once all is out");
        assert!(
            slots.registry.slots[0].views[0].busy,
            "the separator goes now"
        );
    }

    /// TASK-024 item 1: a refused line of an ended session that keeps
    /// failing is given up after [`stream::MAX_RESENDS`] tries, and the next
    /// separator goes.
    #[tokio::test]
    async fn refused_lines_of_an_ended_session_are_given_up_after_a_bounded_number_of_tries() {
        let dir = TempDir::new("slots-stream-drain-give-up");
        let mut slots = asked_slots(&dir);
        slots.on_agent(AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg: one_prompt_chunk(A),
        });
        slots.on_stream_done(A, 1, bad_gateway());
        slots.on_hook(&hook(
            A,
            HookEvent::SessionEnd {
                reason: None,
                claude_pid: Some(10),
            },
        ));
        let path = transcript_file(&dir, B);
        slots.on_hook(&start_with(B, 11, &path, "startup"));
        // The stalled scheduler never answers the title edit of A's start.
        slots.registry.slots[0].views[0].busy = false;
        for _ in 0..stream::MAX_RESENDS {
            slots.streams.get_mut(A).unwrap().rewind_at = Some(Instant::now());
            slots.pump();
            assert!(!slots.registry.slots[0].views[0].busy);
            slots.on_stream_done(A, 1, bad_gateway());
        }
        slots.streams.get_mut(A).unwrap().rewind_at = Some(Instant::now());
        slots.pump();
        assert!(!slots.streams.contains_key(A), "given up");
        assert_eq!(slots.queued_messages, 0);
        slots.pump();
        assert!(slots.registry.slots[0].views[0].busy, "the separator goes");
    }

    fn stream_chunk(session: &str, from: u64, lines: Vec<StreamLine>) -> AgentEvent {
        AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg: AgentMsg::TranscriptChunk {
                session_id: session.into(),
                from,
                to: lines.last().map_or(from, |line| line.end),
                lines,
                missing: false,
                more: false,
                reset: false,
            },
        }
    }

    /// A prompt line ending at `prompt`, then a turn end at `end`.
    fn turn_lines(text: &str, prompt: u64, end: u64) -> Vec<StreamLine> {
        use crate::wire::StreamItem;
        vec![
            StreamLine {
                end: prompt,
                items: vec![StreamItem::Prompt { text: text.into() }],
            },
            StreamLine {
                end,
                items: vec![StreamItem::TurnEnd],
            },
        ]
    }

    fn topic_gone_error() -> Option<Delivery> {
        Some(Err(ApiError::Telegram {
            code: 400,
            description: "Bad Request: message thread not found".into(),
        }))
    }

    fn session_end(session: &str, pid: u32) -> HookPost {
        hook(
            session,
            HookEvent::SessionEnd {
                reason: None,
                claude_pid: Some(pid),
            },
        )
    }

    /// TASK-024 review 1 through the actor: an answer that went by its
    /// timeout before its turn end was read is refused; the re-read holds it
    /// again, and it goes at its own turn end, right after its lines. The
    /// next turn's answer goes at its own turn end, not shifted.
    #[tokio::test]
    async fn a_refused_unpaired_answer_goes_at_its_own_turn_end_after_the_reread() {
        let dir = TempDir::new("slots-stream-debt-rewind");
        let mut slots = asked_slots(&dir);
        slots.on_hook(&stop(A, Some("x")));
        slots.streams.get_mut(A).unwrap().held[0].until = Instant::now();
        slots.pump();
        assert_eq!(
            slots.streams[A].answer_numbers(),
            [(1, "x")],
            "gone unpaired"
        );
        slots.on_stream_done(A, 1, bad_gateway());
        assert!(slots.streams[A].stuck());
        // The re-read after the retry.
        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(stream_chunk(A, 0, turn_lines("one", 10, 20)));
        let live = &slots.streams[A];
        assert!(live.held.is_empty(), "x goes at its own turn end");
        assert_eq!(
            live.answer_numbers().last().map(|(_, text)| *text),
            Some("x")
        );
        // The next turn.
        slots.on_hook(&stop(A, Some("y")));
        slots.streams.get_mut(A).unwrap().reading = Some((1, Instant::now()));
        slots.on_agent(stream_chunk(A, 20, turn_lines("two", 30, 40)));
        let live = &slots.streams[A];
        assert!(live.held.is_empty(), "y goes at its own turn end");
        assert_eq!(
            live.answer_numbers().last().map(|(_, text)| *text),
            Some("y")
        );
    }

    /// TASK-024 fix: a refused stream sleeps until its retry instead of
    /// waking the actor in a loop, and so does the drain of its session
    /// once it left the slot.
    #[tokio::test]
    async fn a_refused_stream_wakes_the_actor_at_its_retry_not_before() {
        let dir = TempDir::new("slots-stream-retry-sleep");
        let mut slots = asked_slots(&dir);
        slots.on_agent(AgentEvent::Message {
            conn: 1,
            received_at: StdInstant::now(),
            msg: one_prompt_chunk(A),
        });
        slots.on_stream_done(A, 1, bad_gateway());
        // The next read time of the chunk passes.
        tokio::time::sleep(Duration::from_millis(50)).await;
        slots.pump();
        let retry = slots.streams[A].rewind_at.expect("a retry");
        let deadline = slots.next_deadline();
        assert!(deadline > Instant::now(), "no busy loop");
        assert!(deadline <= retry, "awake for the retry");
        slots.on_hook(&session_end(A, 10));
        slots.pump();
        assert!(slots.streams.contains_key(A), "draining");
        let deadline = slots.next_deadline();
        assert!(deadline > Instant::now() && deadline <= retry);
    }

    /// TASK-024 review 3: a drain whose topic is gone ends at once, so the
