        assert_eq!(texts, [buffer::OLD_AGENT_NOTICE, buffer::OLD_AGENT_NOTICE]);
        assert_eq!(reacted, [2, 4]);
        assert!(slots.fetching.is_empty());
        assert!(slots.registry.slots[0].buffer.is_idle());
