    /// The move of an old pin a prompt superseded (TASK-062 code review):
    /// the other slot's old pin moves meanwhile, and the two never move at
    /// once, also when the prompt went below the first one.
    #[tokio::test]
    async fn a_superseded_old_pin_move_waits_for_the_other_slots_move() {
        let dir = TempDir::new("slots-rolling-superseded-pin");
        let (_fake, mut slots) = live_slots(&dir, status_options());
        slots.on_hook(&start(A, 10));
        slots.on_hook(&start(B, 11));
        for (index, topic) in [(0, 100), (1, 101)] {
            slots
                .registry
                .topic_created(SlotId(index), Chat::GROUP, topic, "a", None);
            slots.registry.slots[index].views[0].pending_separator = None;
            slots.registry.slots[index].views[0].status = Some(StatusMessage {
                message_id: 500 + topic,
                pinned: true,
            });
        }
        let (place, other) = (
            Place::topic(Chat::GROUP, 100),
            Place::topic(Chat::GROUP, 101),
        );
        let mut work = capture_dispatch(&mut slots);
        // Answers the edits in place; the moves are returned.
        let answer_edits = |slots: &mut Slots, handed: Vec<(StatusJob, Op)>| {
            let mut moves = Vec::new();
            for (job, _) in handed {
                match &job {
                    StatusJob::Edit { message, .. } => {
                        let slot = SlotId(usize::from(message.id == 601));
                        slots.on_status_done(slot, job, Some(Ok(Outcome::Done)));
                    }
                    _ => moves.push(job),
                }
            }
            moves
        };
        slots.pump();
        let mut moves = answer_edits(&mut slots, status_work(&mut work));
        assert_eq!(moves.len(), 1, "{moves:?}");
        let first = moves.remove(0);
        assert!(
            matches!(&first, StatusJob::Replace { old, pinned: true, .. } if old.id == 600),
            "{first:?}"
        );
        // A prompt of topic 100 supersedes it.
        slots.hand_off(Work::Message, message_op(place, "prompt".to_owned()));
        slots.on_done(Done::Posted {
            place,
            message_id: None,
        });
        slots.on_status_done(SlotId(0), first, Some(Ok(Outcome::Superseded)));
        assert!(!slots.shown[&SlotId(0)].migrating);
        assert!(!slots.bottoms[&place].foreign, "it stays an old pin");
        // The other slot's old pin moves meanwhile.
        slots.pump();
        let mut moves = answer_edits(&mut slots, status_work(&mut work));
        assert_eq!(moves.len(), 1, "{moves:?}");
        let second = moves.remove(0);
        assert!(
            matches!(&second, StatusJob::Replace { old, pinned: true, .. } if old.id == 601),
            "{second:?}"
        );
        // The prompt went below the first one; its move waits for the other.
        slots.on_done(Done::Posted {
            place,
            message_id: Some(610),
        });
        slots.pump();
        let moves = answer_edits(&mut slots, status_work(&mut work));
        assert!(moves.is_empty(), "one old pin at a time: {moves:?}");
        slots.on_done(Done::Posted {
            place: other,
            message_id: Some(700),
        });
        slots.on_status_done(
            SlotId(1),
            second,
            Some(Ok(Outcome::Sent(Message {
                message_id: 700,
                ..Message::default()
            }))),
        );
        slots.pump();
        let moves = answer_edits(&mut slots, status_work(&mut work));
        assert!(
            matches!(
                moves.as_slice(),
                [StatusJob::Replace { old, pinned: true, .. }] if old.id == 600
            ),
            "then it moves, below the prompt: {moves:?}"
        );
    }

    /// Two prompts in a row in one topic (TASK-062 code review): each drops
    /// the status move queued before it, and the status message ends up
    /// below the second.
    #[tokio::test]
    async fn two_prompts_in_a_row_leave_the_status_message_below_the_second() {
        let dir = TempDir::new("slots-rolling-two-prompts");
        let (_fake, mut slots) = live_slots(&dir, status_options());
        slots.on_hook(&start(A, 10));
        slots
            .registry
            .topic_created(SlotId(0), Chat::GROUP, 100, "a", None);
        slots.registry.slots[0].views[0].pending_separator = None;
        slots.registry.slots[0].views[0].status = Some(StatusMessage {
            message_id: 500,
            pinned: false,
        });
        let place = Place::topic(Chat::GROUP, 100);
        slots.bottoms.entry(place).or_default().last = 501;
        let mut work = capture_dispatch(&mut slots);
        // Answers the edits in place; the moves are returned.
        let answer_edits = |slots: &mut Slots, handed: Vec<(StatusJob, Op)>| {
            let mut moves = Vec::new();
            for (job, _) in handed {
                match job {
                    StatusJob::Edit { .. } => {
                        slots.on_status_done(SlotId(0), job, Some(Ok(Outcome::Done)));
                    }
                    job => moves.push(job),
                }
            }
            moves
        };
        for (prompt, posted) in [("first", 502), ("second", 503)] {
            slots.pump();
            let mut moves = answer_edits(&mut slots, status_work(&mut work));
            assert_eq!(moves.len(), 1, "{prompt}: {moves:?}");
            let job = moves.remove(0);
            assert!(
                matches!(&job, StatusJob::Replace { old, .. } if old.id == 500),
                "{prompt}: {job:?}"
            );
            slots.hand_off(Work::Message, message_op(place, prompt.to_owned()));
            slots.on_done(Done::Posted {
                place,
                message_id: None,
            });
            slots.on_status_done(SlotId(0), job, Some(Ok(Outcome::Superseded)));
            slots.pump();
            let moves = answer_edits(&mut slots, status_work(&mut work));
            assert!(moves.is_empty(), "{prompt} is on its way: {moves:?}");
            slots.on_done(Done::Posted {
                place,
                message_id: Some(posted),
            });
        }
        slots.pump();
        let mut moves = answer_edits(&mut slots, status_work(&mut work));
        assert_eq!(moves.len(), 1, "{moves:?}");
        let job = moves.remove(0);
        assert!(
            matches!(&job, StatusJob::Replace { old, .. } if old.id == 500),
            "{job:?}"
        );
        slots.on_done(Done::Posted {
            place,
            message_id: Some(504),
        });
        slots.on_status_done(
            SlotId(0),
            job,
            Some(Ok(Outcome::Sent(Message {
                message_id: 504,
                ..Message::default()
            }))),
        );
        assert_eq!(
            slots.registry.slots[0].views[0].status,
            Some(StatusMessage {
                message_id: 504,
                pinned: false
            })
        );
        assert_eq!(
            slots.absorbable(SlotId(0), place),
            Some(MessageKey::new(Chat::GROUP, 504)),
            "below the second prompt (503), the last message of its topic"
        );
    }

    /// Private chats on with one owner; new slots shared to the group too,
    /// for the mirror (TASK-063).
    fn private_options() -> Options {
        Options {
            owners: Some(Owners {
                first: PrivateChat::of_user(7),
                devices: None,
                share_new: true,
            }),
            ..message_options()
        }
    }

    /// TASK-063 (decision 2026-09-28): a new slot shows in its owner's
    /// private chat alone; with that chat closed (403) it shows in the
    /// group, and a slot whose private view is not usable gets the group.
    #[tokio::test]
    async fn a_new_slot_shows_in_the_private_chat_alone_or_else_in_the_group() {
        let dir = TempDir::new("slots-private-home");
        let options = Options {
            owners: Some(Owners {
                first: PrivateChat::of_user(7),
                devices: None,
                share_new: false,
            }),
            ..message_options()
        };
        let mut slots = stalled_slots(&dir, options);
        let owner = private_owner();
        slots.on_hook(&start(A, 10));
        assert_eq!(
            slots.registry.slots[0].views,
            [crate::hub::registry::View::new(owner)]
        );
        slots.pump();
        assert_eq!(slots.registry.slots[0].views.len(), 1, "no group view");
        // The owner blocked the bot: the slot shows in the group too.
        let Chat::Private(private) = owner else {
            unreachable!()
        };
        slots.registry.closed.insert(private);
        slots.pump();
        let chats: Vec<(Chat, bool)> = slots.registry.slots[0]
            .views
            .iter()
            .map(|view| (view.chat, view.fallback))
            .collect();
        assert_eq!(chats, [(owner, false), (Chat::GROUP, true)]);
        // A new slot while the chat is closed: the group, as before, until
        // the chat opens.
        slots.on_hook(&start(B, 11));
        assert_eq!(
            slots.registry.slots[1].views,
            [crate::hub::registry::View {
                fallback: true,
                ..crate::hub::registry::View::new(Chat::GROUP)
            }]
        );
    }

    fn private_owner() -> Chat {
        Chat::Private(PrivateChat::of_user(7))
    }

    /// Private chats on as the hub runs: new slots in the private chat alone.
    fn private_only_options() -> Options {
        Options {
            owners: Some(Owners {
                first: PrivateChat::of_user(7),
                devices: None,
                share_new: false,
            }),
            ..message_options()
        }
    }

    /// TASK-063 (code review 6): a slot that got a group view only because
    /// its private chat was closed leaves the group once that chat opens and
    /// has the session again: its group topic is told and gets the dead
    /// icon. A slot shared from the start keeps its group view.
    #[tokio::test]
    async fn a_slot_in_the_group_for_a_closed_chat_leaves_it_once_the_chat_opens() {
        let dir = TempDir::new("slots-private-fallback");
        let mut slots = stalled_slots(&dir, private_only_options());
        let owner = private_owner();
        let Chat::Private(private) = owner else {
            unreachable!()
        };
        slots.on_hook(&start(A, 10));
        slots
            .registry
            .topic_created(SlotId(0), owner, 700, "t", None);
        slots.close_chat(owner);
        slots.pump();
        slots
            .registry
            .topic_created(SlotId(0), Chat::GROUP, 100, "t", None);
        // A slot shared from before: its group view is no fallback.
        slots.on_hook(&start(B, 11));
        slots.registry.slots[1].views = vec![
            crate::hub::registry::View::new(Chat::GROUP),
            crate::hub::registry::View::new(owner),
        ];
        slots
            .registry
            .topic_created(SlotId(1), Chat::GROUP, 101, "t", None);
        slots
            .registry
            .topic_created(SlotId(1), owner, 701, "t", None);
        slots.pump();
        assert_eq!(
            slots.registry.place(SlotId(0)),
            Some(Place::topic(Chat::GROUP, 100))
        );
        let mut work = capture_dispatch(&mut slots);
        // Still closed: nothing changes.
        slots.pump();
        assert_eq!(slots.registry.slots[0].views.len(), 2);
        // The owner writes to the bot.
        slots.reopen(owner);
        assert!(slots.proven.contains(&private));
        slots.pump();
        let chats: Vec<Chat> = slots.registry.slots[0]
            .views
            .iter()
            .map(|view| view.chat)
            .collect();
        assert_eq!(chats, [owner], "the private chat alone again");
        assert_eq!(
            slots.registry.place(SlotId(0)),
            Some(Place::topic(owner, 700))
        );
        assert_eq!(
            slots.registry.slots[1].views.len(),
            2,
            "a shared slot stays"
        );
        let group: Vec<Op> = all_work(&mut work)
            .into_iter()
            .map(|(_, op)| op)
            .filter(|op| op.chat() == Some(Chat::GROUP))
            .collect();
        assert!(
            group.iter().any(
                |op| matches!(op, Op::Send { thread_id: Some(100), text, .. }
                if text == FALLBACK_END_NOTICE)
            ),
            "{group:#?}"
        );
        assert!(
            group.iter().any(|op| matches!(op, Op::EditTopic { thread_id: 100, icon_custom_emoji_id: Some(icon), .. }
                if Some(icon.as_str()) == slots.options.icons.for_state(SlotState::Dead))),
            "{group:#?}"
        );
        assert!(
            group
                .iter()
                .all(|op| op.place().is_none_or(|place| place.thread != Some(101))),
            "nothing for the shared slot's group topic: {group:#?}"
        );
    }

