        let store = RegistryStore::open(dir.path()).unwrap();
        let stalled = Arc::new(Fake {
            stall: true,
            ..Fake::default()
        });
        let (scheduler, outbox) = Scheduler::new(stalled, BucketConfig::default());
        tokio::spawn(scheduler.run());
